const unsigned char *get_big_icon(const std::string &weather)
{
    if (weather == "Clear") return bmp_clear;
    if (weather == "Clouds") return bmp_clouds;
    if (weather == "Rain" || weather == "Drizzle" || weather == "Thunderstorm") return bmp_rain;
    return bmp_clouds;
}

const unsigned char *get_mini_icon(const std::string &weather)
{
    if (weather == "Clear") return mini_sun;
    if (weather == "Rain" || weather == "Drizzle" || weather == "Thunderstorm") return mini_rain;
    return mini_cloud;
}
